<?php
namespace App\Domain\Tax\Actions;
use App\Models\{CheckoutTaxLine,Order,OrderTaxLine,TaxClass,TaxJurisdiction};
/** Defines the SnapshotOrderTaxes class and its project responsibilities. */
class SnapshotOrderTaxes { public function execute(Order $order):void { if(OrderTaxLine::query()->where('order_id',$order->id)->exists())return;$order->load(['checkoutSession.taxLines.jurisdiction','checkoutSession.taxLines.taxClass','items','vendorOrders']);$itemMap=$order->items->filter(/** Inline callback for this operation. */ fn($x)=>$x->checkout_session_item_id)->keyBy('checkout_session_item_id');$vendorMap=$order->vendorOrders->keyBy(/** Inline callback for this operation. */ fn($v)=>(string)($v->vendor_id??0));foreach($order->checkoutSession->taxLines as $l){$oi=$l->checkout_session_item_id?$itemMap->get($l->checkout_session_item_id):null;$vo=$vendorMap->get((string)($l->vendor_id??0));OrderTaxLine::create(['order_id'=>$order->id,'vendor_order_id'=>$vo?->id,'order_item_id'=>$oi?->id,'source'=>$l->source,'source_reference'=>$l->source_reference,'jurisdiction_name'=>$l->jurisdiction?->name,'tax_class_code'=>$l->taxClass?->code,'label'=>$l->label,'rate_bps'=>$l->rate_bps,'taxable_minor'=>$l->taxable_minor,'tax_minor'=>$l->tax_minor,'price_includes_tax'=>$l->price_includes_tax,'liability_bearer'=>$l->liability_bearer,'metadata'=>$l->metadata]);} } }